$count = 0
$total = $images.Count
$errors = @()

foreach ($entry in $images.GetEnumerator()) {
    $count++
    $path = Join-Path $base $entry.Key
    $dir = Split-Path $path -Parent
    if (!(Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    
    try {
        $wc = New-Object System.Net.WebClient
        $wc.DownloadFile($entry.Value, $path)
        $wc.Dispose()
        Write-Output "[$count/$total] OK: $($entry.Key)"
    } catch {
        $errors += "$($entry.Key): $($_.Exception.Message)"
        Write-Output "[$count/$total] FAIL: $($entry.Key) - $($_.Exception.Message)"
    }
}

Write-Output ""
Write-Output "DONE: $($images.Count - $errors.Count)/$($images.Count) downloaded"
if ($errors.Count -gt 0) { Write-Output "ERRORS: $($errors.Count) failures" }
